function main(): void {
/**
 * Author: Mathias Bynens <http://mathiasbynens.be/>
 * Author: Ms2ger <mailto:Ms2ger@gmail.com>
 *
 * Spec: <https://xhr.spec.whatwg.org/#the-responsetype-attribute>
 */
test(function() {
  var xhr = new XMLHttpRequest();
  assert_equals(xhr.responseType, '');
}, 'Initial value of responseType');

var types = ['', 'json', 'document', 'arraybuffer', 'blob', 'text', "nosuchtype"];

function isIgnoredType(type) {
  if (type == "nosuchtype") {
    return true;
  }

  if (type != "document") {
    return false;
  }

  // "document" is ignored only on workers.
  return GLOBAL.isWorker();
}

function expectedType(type) {
  if (!isIgnoredType(type)) {
    return type;
  }

  return "";
}

types.forEach(function(type) {
  test(function() {
    var xhr = new XMLHttpRequest();
    xhr.responseType = type;
    assert_equals(xhr.responseType, expectedType(type));
  }, 'Set responseType to ' + format_value(type) + ' when readyState is UNSENT.');

  test(function() {
    var xhr = new XMLHttpRequest();
    xhr.open('get', '/');
    xhr.responseType = type;
    assert_equals(xhr.responseType, expectedType(type));
  }, 'Set responseType to ' + format_value(type) + ' when readyState is OPENED.');

  async_test(function() {
    var xhr = new XMLHttpRequest();
    xhr.open('get', '/');
    xhr.onreadystatechange = this.step_func(function() {
      if (xhr.readyState === XMLHttpRequest.HEADERS_RECEIVED) {
        xhr.responseType = type;
        assert_equals(xhr.responseType, expectedType(type));
        this.done();
      }
    });
    xhr.send();
  }, 'Set responseType to ' + format_value(type) + ' when readyState is HEADERS_RECEIVED.');

  async_test(function() {
    var xhr = new XMLHttpRequest();
    xhr.open('get', '/');
    xhr.onreadystatechange = this.step_func(function() {
      if (xhr.readyState === XMLHttpRequest.LOADING) {
        if (isIgnoredType(type)) {
          xhr.responseType = type;
        } else {
          assert_throws_dom("InvalidStateError", function() {
            xhr.responseType = type;
          });
        }
        assert_equals(xhr.responseType, "");
        this.done();
      }
    });
    xhr.send();
  }, 'Set responseType to ' + format_value(type) + ' when readyState is LOADING.');

  async_test(function() {
    var xhr = new XMLHttpRequest();
    xhr.open('get', '/');
    xhr.onreadystatechange = this.step_func(function() {
      if (xhr.readyState === XMLHttpRequest.DONE) {
        var text = xhr.responseText;
        assert_not_equals(text, "");
        if (isIgnoredType(type)) {
          xhr.responseType = type;
        } else {
          assert_throws_dom("InvalidStateError", function() {
            xhr.responseType = type;
          });
        }
        assert_equals(xhr.responseType, "");
        assert_equals(xhr.responseText, text);
        this.done();
      }
    });
    xhr.send();
  }, 'Set responseType to ' + format_value(type) + ' when readyState is DONE.');

  // Note: the case of setting responseType first, and then calling synchronous
  // open(), is tested in open-method-responsetype-set-sync.htm.
  test(function() {
    var xhr = new XMLHttpRequest();
    xhr.open('get', '/', false);
    if (GLOBAL.isWorker() || isIgnoredType(type)) {
      // Setting responseType on workers is valid even for a sync XHR.
      xhr.responseType = type;
      assert_equals(xhr.responseType, expectedType(type));
    } else {
      assert_throws_dom("InvalidAccessError", function() {
        xhr.responseType = type;
      });
    }
  }, 'Set responseType to ' + format_value(type) + ' when readyState is OPENED and the sync flag is set.');

  test(function() {
    var xhr = new XMLHttpRequest();
    xhr.open('get', '/', false);
    xhr.send();
    assert_equals(xhr.readyState, XMLHttpRequest.DONE);
    if (isIgnoredType(type)) {
      xhr.responseType = type;
    } else {
      assert_throws_dom("InvalidStateError", function() {
        xhr.responseType = type;
      });
    }
    assert_equals(xhr.responseType, "");
  }, 'Set responseType to ' + format_value(type) + ' when readyState is DONE and the sync flag is set.');
});
}
main();

function main(): void {
// https://xhr.spec.whatwg.org/#the-abort()-method
// abort() sets the response to a network error, both via the request error steps (step 2) and
// when the state is already done (step 3). A network error's URL is null, so responseURL must
// return the empty string, just like status is 0 and getAllResponseHeaders() is "".

const url = "resources/well-formed.xml";

function assertNetworkError(client) {
  assert_equals(client.status, 0, "status");
  assert_equals(client.statusText, "", "statusText");
  assert_equals(client.getAllResponseHeaders(), "", "getAllResponseHeaders()");
  assert_equals(client.responseURL, "", "responseURL");
}

async_test(test => {
  const client = new XMLHttpRequest();
  client.onreadystatechange = test.step_func(() => {
    if (client.readyState !== 2)
      return;
    assert_equals(client.status, 200);
    assert_not_equals(client.responseURL, "", "responseURL before abort()");
    client.abort();
    assertNetworkError(client);
  });
  client.onloadend = test.step_func_done(() => {
    assertNetworkError(client);
  });
  client.open("GET", url);
  client.send(null);
}, "abort() during HEADERS_RECEIVED clears responseURL");

async_test(test => {
  const client = new XMLHttpRequest();
  let aborted = false;
  client.onreadystatechange = test.step_func(() => {
    if (client.readyState !== 3 || aborted)
      return;
    aborted = true;
    assert_equals(client.status, 200);
    assert_not_equals(client.responseURL, "", "responseURL before abort()");
    client.abort();
    assertNetworkError(client);
  });
  client.onloadend = test.step_func_done(() => {
    assert_true(aborted, "reached LOADING");
    assertNetworkError(client);
  });
  client.open("GET", url);
  client.send(null);
}, "abort() during LOADING clears responseURL");

async_test(test => {
  const client = new XMLHttpRequest();
  client.onload = test.step_func_done(() => {
    assert_equals(client.readyState, 4);
    assert_not_equals(client.responseURL, "", "responseURL before abort()");
    client.abort();
    assert_equals(client.readyState, 0);
    assertNetworkError(client);
  });
  client.open("GET", url);
  client.send(null);
}, "abort() during DONE clears responseURL (async)");

test(() => {
  const client = new XMLHttpRequest();
  client.open("GET", url, false);
  client.send(null);
  assert_equals(client.readyState, 4);
  assert_not_equals(client.responseURL, "", "responseURL before abort()");
  client.abort();
  assert_equals(client.readyState, 0);
  assertNetworkError(client);
}, "abort() during DONE clears responseURL (sync)");

async_test(test => {
  const client = new XMLHttpRequest();
  client.open("GET", url);
  client.send(null);
  client.abort();
  assertNetworkError(client);
  // A reused XMLHttpRequest must report the new response's URL, not the aborted one.
  client.onload = test.step_func_done(() => {
    assert_equals(client.status, 200);
    assert_equals(client.responseURL, new URL(url + "?reused", location.href).href);
  });
  client.open("GET", url + "?reused");
  client.send(null);
}, "responseURL reflects the new response after abort() and reuse");
}
main();

